package com.wartec.flightqa;

import com.google.gson.*;
import com.mojang.authlib.GameProfile;
import com.wartec.wartecmod.port.content.*;
import com.wartec.wartecmod.port.entity.*;
import com.wartec.wartecmod.port.gameplay.*;
import com.wartec.wartecmod.port.gui.*;
import com.wartec.wartecmod.port.integration.*;
import com.wartec.wartecmod.port.network.*;
import com.wartec.wartecmod.port.planning.*;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import net.minecraft.entity.Entity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.*;
import net.minecraft.util.math.*;
import net.minecraft.world.WorldServer;
import net.minecraftforge.common.*;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.fml.common.FMLCommonHandler;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;

/** Native command service and scheduler; all fake actors and synthetic observation controls stay here. */
public final class CommandCenterQa {
    private WorldServer world;private int tick;private Pilot owner,operator,observer,enemy;private TileEntityPlanningTerminal terminal;
    private EntityStrategicTel tel;private EntityModernVehicle radar;private EntityWarTechGroundVehicle battery;private EntityWarTechMissile target;
    private AttackOperation intelPlan,revokedPlan;private String batteryKey;private long batteryId;private CommandCenterState state;
    private final List<ForgeChunkManager.Ticket> tickets=new ArrayList<>();private final JsonArray cases=new JsonArray();private final List<String> failures=new ArrayList<>();
    private final BlockPos anchor=new BlockPos(41008,80,41008);
    private static final class Pilot extends FakePlayer {Pilot(WorldServer w,int n,String team){super(w,new GameProfile(new UUID(109,n),"CommandQA"+n));NetworkTeamHelper.setPlayerTeam(this,team);capabilities.isCreativeMode=true;}@Override public void closeScreen(){openContainer=inventoryContainer;}}
    public void started(){if(!Files.isRegularFile(Paths.get("FLIGHT_QA_ISOLATED")))throw new IllegalStateException("Not isolated");world=FMLCommonHandler.instance().getMinecraftServerInstance().getWorld(0);world.getGameRules().setOrCreateGameRule("doMobSpawning","false");MinecraftForge.EVENT_BUS.register(this);}
    private void check(String key,boolean ok,Object detail){JsonObject n=new JsonObject();n.addProperty("kind",key);n.addProperty("success",ok);n.addProperty("detail",String.valueOf(detail));cases.add(n);if(!ok)failures.add(key+": "+detail);System.out.println("COMMANDQA "+n);}
    private void pin(int x,int z){ForgeChunkManager.Ticket ticket=ForgeChunkManager.requestTicket(com.wartec.wartecmod.WarTechReforged.instance,world,ForgeChunkManager.Type.NORMAL);tickets.add(ticket);for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++){ChunkPos p=new ChunkPos((x>>4)+dx,(z>>4)+dz);world.getChunkFromChunkCoords(p.x,p.z);ForgeChunkManager.forceChunk(ticket,p);}}
    private void platform(int x,int z){pin(x,z);for(int dx=-7;dx<=7;dx++)for(int dz=-7;dz<=7;dz++)world.setBlockState(new BlockPos(x+dx,79,z+dz),net.minecraft.init.Blocks.STONE.getDefaultState(),2);}
    private void container(Pilot p,int id){p.setPosition(anchor.getX()+1,80,anchor.getZ()+1);p.openContainer=new ContainerPlanningTerminal(p,terminal,null);p.openContainer.windowId=id;}
    private NBTTagCompound request(Pilot p,String action,NBTTagCompound payload){NBTTagCompound n=new NBTTagCompound();n.setString("Action",action);n.setInteger("Serial",tick);n.setBoolean("Workspace",true);n.setInteger("WorkspaceTab",1);n.setInteger("Radius",256);n.setDouble("X",anchor.getX());n.setDouble("Z",anchor.getZ());n.setLong("CommandRevision",state==null?0:state.revision);n.merge(payload);return PlanningService.handle(p,p.openContainer.windowId,n);}
    private NBTTagCompound keys(String key){NBTTagCompound n=new NBTTagCompound();NBTTagList list=new NBTTagList();list.appendTag(new NBTTagString(key));n.setTag("FleetKeys",list);return n;}
    private void setup(){FactionTerritoryData.claimAt(world,"command-blue",anchor.getX()+80,anchor.getZ()+48);owner=new Pilot(world,1,"command-blue");operator=new Pilot(world,2,"command-blue");observer=new Pilot(world,3,"command-blue");enemy=new Pilot(world,4,"command-red");platform(anchor.getX(),anchor.getZ());world.setBlockState(anchor,WarTechContent.PLANNING_TERMINAL.getDefaultState());terminal=(TileEntityPlanningTerminal)world.getTileEntity(anchor);PlanningAccessPolicy.claim(terminal,owner);container(owner,501);container(operator,502);container(observer,503);container(enemy,504);
        NBTTagCompound snapshot=request(owner,"fetch",new NBTTagCompound());state=PlanningWorldData.get(world).command(PlanningAccessPolicy.scope(owner));check("owned_hq_bootstrap",state.role(owner.getUniqueID())==CommandCenterState.Role.COMMANDER,snapshot.getCompoundTag("Command"));state.roles.put(operator.getUniqueID(),CommandCenterState.Role.OBSERVER);state.roles.put(observer.getUniqueID(),CommandCenterState.Role.OBSERVER);
        tel=new EntityStrategicTel(world,StrategicSystemProfile.TOPOL_M);tel.setOwnerIdentity(owner.getUniqueID(),"command-blue");tel.setPosition(anchor.getX()+64,80,anchor.getZ());platform((int)tel.posX,(int)tel.posZ);tel.setMissileLoaded(true);check("native_tel",world.spawnEntity(tel),"loaded native TEL");
        radar=new EntityModernVehicle(world,ModernVehicleProfile.RADAR_9S18);radar.setOwnerIdentity(owner.getUniqueID(),"command-blue");radar.setPosition(anchor.getX()+80,80,anchor.getZ()+48);platform((int)radar.posX,(int)radar.posZ);radar.setDeployed(true);radar.setLegacyPower(radar.getEnergyCapacity());check("native_radar",world.spawnEntity(radar),"physical 9S18");
        battery=new EntityWarTechGroundVehicle(world,WarTechEntityProfile.MOBILE_AIR_DEFENSE);battery.setVisual("mobile_air_defense",1);battery.setOwnerIdentity(owner.getUniqueID(),"command-blue");battery.setPosition(anchor.getX()+32,80,anchor.getZ()+32);platform((int)battery.posX,(int)battery.posZ);battery.setDeployed(true);battery.setLegacyFireMode(0);battery.setLegacyPower(battery.getEnergyCapacity());check("native_battery",world.spawnEntity(battery),"native launcher, automatic fire intentionally off for admission probes");batteryKey=PlanningAssetRegistry.key(battery);batteryId=battery.commandDefenseTelemetry().getLong("Key");PlanningAssetRegistry.refresh(world);
        intelPlan=new AttackOperation();intelPlan.scope=PlanningAccessPolicy.scope(owner);intelPlan.author=owner.getUniqueID();intelPlan.title="Fresh intel gate";AttackOperation.Step s=new AttackOperation.Step();s.asset=PlanningAssetRegistry.key(tel);s.action=AttackOperation.Action.PREPARE;s.condition=AttackOperation.Condition.FRESH_INTEL;s.x=anchor.getX()+120;s.y=80;s.z=anchor.getZ();s.deadline=1000;intelPlan.steps.add(s);intelPlan.started=world.getTotalWorldTime();intelPlan.state=AttackOperation.State.RUNNING;PlanningWorldData.get(world).operations.put(intelPlan.id,intelPlan);
    }
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e)throws Exception{if(e.phase!=TickEvent.Phase.END)return;tick++;
        if(tick==1)setup();
        if(tick==10){NBTTagCompound p=new NBTTagCompound();p.setUniqueId("Player",operator.getUniqueID());p.setString("Role","OPERATOR");NBTTagCompound n=request(owner,"cc_role",p);check("grant_known_member",n.getString("Error").isEmpty() && state.role(operator.getUniqueID())==CommandCenterState.Role.OPERATOR,n.getString("Error"));}
        if(tick==20){NBTTagCompound p=keys(batteryKey),meta=new NBTTagCompound();meta.setString("Group","North");meta.setString("Title","North battery");meta.setInteger("ReserveTier",2);p.setTag("Fleet",meta);p.setBoolean("Rename",true);NBTTagCompound n=request(operator,"cc_fleet",p);check("operator_fleet_write",n.getString("Error").isEmpty() && "North".equals(state.fleet.get(batteryKey).getString("Group")),n.getString("Error"));}
        if(tick==30){NBTTagCompound p=keys(batteryKey);p.setTag("Fleet",new NBTTagCompound());NBTTagCompound n=request(observer,"cc_fleet",p);check("observer_write_denied","access".equals(n.getString("Error")),n.getString("Error"));check("waits_for_observation",!tel.isDeployed() && intelPlan.steps.get(0).phase==AttackOperation.Phase.WAITING,intelPlan.steps.get(0).reason);}
        if(tick==40){NBTTagCompound n=request(enemy,"fetch",new NBTTagCompound());check("foreign_session_denied",n==null,"no other team's snapshot");}
        if(tick==50){AttackOperation.Step s=intelPlan.steps.get(0);PlanningWorldData.get(world).intel(intelPlan.scope).cell(Math.floorDiv(s.x,16),Math.floorDiv(s.z,16),80,0x557755,world.getTotalWorldTime(),"QA controlled observation",owner.getUniqueID());}
        if(tick==180){check("fresh_observation_unblocks_native_prepare",intelPlan.state==AttackOperation.State.COMPLETE && tel.getErectionProgress()==100,intelPlan.state+"/"+tel.getErectionProgress());check("prepare_did_not_launch",tel.isMissileLoaded(),"no missile consumed");
            target=LegacyEntityFactory.missile(world,MissileProfile.SMERCH_ROCKET);target.setOwnerIdentity(enemy.getUniqueID(),"command-red");target.setPosition(anchor.getX()+180,120,anchor.getZ()+32);target.configureLegacyGroundLaunch(anchor.getX()+32,80,anchor.getZ()+32);pin((int)target.posX,(int)target.posZ);pin(anchor.getX()+130,anchor.getZ()+32);target.ticksExisted=100;check("frozen_native_contact",world.spawnEntity(target),"stationary admission probe, not an intercept proof");target.updateBlocked=true;}
        if(tick==210){NBTTagCompound p=new NBTTagCompound();p.setInteger("DiagnosticTarget",target.getEntityId());NBTTagCompound n=request(owner,"fetch",p);check("real_radar_contact",n.getCompoundTag("Command").getCompoundTag("Summary").getInteger("Threats")>0,n.getCompoundTag("Command").getCompoundTag("Summary"));check("diagnostic_rows",n.getCompoundTag("Command").getTagList("Diagnostics",10).tagCount()>0,n.getCompoundTag("Command").getTagList("Diagnostics",10));p.setInteger("DiagnosticTarget",Integer.MAX_VALUE);check("guessed_target_is_not_disclosed",request(observer,"fetch",p).getCompoundTag("Command").getTagList("Diagnostics",10).tagCount()==0,"unknown entity id");}
        if(tick==220){NBTTagCompound p=new NBTTagCompound();p.setString("Asset",batteryKey);p.setString("Kind","ammo");p.setString("SupportGroup","Supply");NBTTagCompound n=request(operator,"cc_task",p);check("supply_request_created",n.getString("Error").isEmpty() && state.tasks.size()==1,n.getString("Error"));battery.setInventorySlotContents(0,new ItemStack(WarTechContent.ITEM_MISSILE_ANTI_AIR_TIER_1));}
        if(tick==250){check("supply_completed_from_real_inventory",state.tasks.values().iterator().next().getBoolean("Done"),state.tasks);NBTTagCompound p=keys(batteryKey),meta=new NBTTagCompound();meta.setString("Group","North");meta.setInteger("Reserve",1);meta.setInteger("ReserveTier",2);p.setTag("Fleet",meta);check("reserve_setting",request(operator,"cc_fleet",p).getString("Error").isEmpty(),"one rocket reserved for tier2+");}
        if(tick==260){PlanningAssetRegistry.refresh(world);MissileTrackingService.updateLauncherPresence(world,battery.posX,battery.posY+3,battery.posZ,1,batteryId,battery.getOwnerTeam());check("native_reservation_respects_live_reserve",!MissileTrackingService.tryReserve(world,target.getEntityId(),batteryId),"tier1 target and one actual missile");NBTTagCompound p=keys(batteryKey),meta=new NBTTagCompound();meta.setString("Group","North");meta.setInteger("ReserveTier",2);p.setTag("Fleet",meta);check("reserve_cleared",request(operator,"cc_fleet",p).getString("Error").isEmpty(),"no reserve");}
        if(tick==290){check("native_reservation_restored",MissileTrackingService.tryReserve(world,target.getEntityId(),batteryId),"new policy releases ordinary admission");MissileTrackingService.releaseReservation(world,target.getEntityId(),batteryId);target.setDead();
            revokedPlan=new AttackOperation();revokedPlan.scope=intelPlan.scope;revokedPlan.author=operator.getUniqueID();revokedPlan.state=AttackOperation.State.RUNNING;revokedPlan.started=world.getTotalWorldTime();AttackOperation.Step s=new AttackOperation.Step();s.asset=PlanningAssetRegistry.key(tel);s.action=AttackOperation.Action.LAUNCH;s.x=anchor.getX()+500;s.y=80;s.z=anchor.getZ();s.offset=200;revokedPlan.steps.add(s);PlanningWorldData.get(world).operations.put(revokedPlan.id,revokedPlan);}
        if(tick==300){NBTTagCompound p=new NBTTagCompound();p.setUniqueId("Player",operator.getUniqueID());p.setString("Role","OBSERVER");check("revoke_operator",request(owner,"cc_role",p).getString("Error").isEmpty(),"saved role revoked");}
        if(tick==330){check("revocation_pauses_scheduler",revokedPlan.state==AttackOperation.State.PAUSED && "mandate".equals(revokedPlan.reason),revokedPlan.state+"/"+revokedPlan.reason);check("revocation_does_not_consume_weapon",tel.isMissileLoaded() && tel.getLaunchTicks()==0,"no launch after permission revocation");PlanningWorldData d=PlanningWorldData.get(world),copy=new PlanningWorldData();copy.readFromNBT(d.writeToNBT(new NBTTagCompound()));check("settings_nbt_restore",copy.command(intelPlan.scope).role(operator.getUniqueID())==CommandCenterState.Role.OBSERVER && "North".equals(copy.command(intelPlan.scope).fleet.get(batteryKey).getString("Group")),"role, group, completed tasks");check("conditional_plan_restore",copy.operations.get(intelPlan.id).steps.get(0).condition==AttackOperation.Condition.FRESH_INTEL,"condition survives persisted plan");}
        if(tick==340){NBTTagCompound p=new NBTTagCompound();p.setInteger("WorkspaceTab",6);NBTTagCompound n=request(owner,"fetch",p);check("recorded_episode_available",n.getCompoundTag("Command").getTagList("Battles",10).tagCount()>0,"actual 9S18 detection");check("notice_no_chat_spam",state.alerts.size()>0 && state.alerts.size()<=CommandCenterState.MAX_ALERTS,state.alerts.size());}
        if(tick==360){for(Entity entity:new ArrayList<>(world.loadedEntityList))if(entity instanceof EntityWarTechBase)entity.setDead();for(ForgeChunkManager.Ticket ticket:tickets)ForgeChunkManager.releaseTicket(ticket);}
        if(tick==420){String resources=MissileChunkLoader.diagnostics(world);check("released_resources",resources.contains("flights=0/") && resources.contains("queue=0 chunks/0 owners"),resources);JsonObject out=new JsonObject();out.addProperty("complete",true);out.add("cases",cases);out.add("failures",new Gson().toJsonTree(failures));out.addProperty("resources",resources);Files.write(Paths.get("flightqa-report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out).getBytes(StandardCharsets.UTF_8));world.getMinecraftServer().initiateShutdown();}
    }
}
